public class Main {
    static void addToEach(int[] values, int delta) {
        for (int i = 0; i < values.length; i++) {
            values[i] = values[i] + delta;
        }
    }
    public static void main(String[] args) {
        int[] values = {1, 2, 3};
        addToEach(values, 1);
        System.out.println(values[0]);
    }
}

